$(document).ready(function() {

    var baseUrl = window.location.origin;

    let get_cusomer_url = baseUrl + '/search_customer';
    let search_on_code = baseUrl + '/search_on_code';
    let search_on_pooja = baseUrl + '/search_on_pooja';
    let update_pooja_values = baseUrl + '/update_pooja_values';

    $.ajaxSetup({
        headers: {
            'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
        }
    });

    // ✅ Get existing customer ID
    var customerId = $('#purchase_customer_id').val();

    // ========================= CUSTOMER SEARCH =========================
    $(document).on('keyup', '.customer_name', function() {

        let value = $(this).val();

        $.ajax({
            url: get_cusomer_url,
            data: { search_value: value },
            type: 'GET',
            success: function(response) {

                let dropdown = $('.dropdown-menu');
                dropdown.empty();

                response.forEach(function(res) {
                    dropdown.append(`
                        <a class="dropdown-item"
                           href="#"
                           data-id="${res.id}"
                           data-name="${res.customer_name}">
                           ${res.customer_name} (${res.mobile_no})
                        </a>
                    `);
                });

                dropdown.show();
            }
        });
    });

    // Select customer
    $('.dropdown-menu').on('click', '.dropdown-item', function(e) {
        e.preventDefault();

        customerId = $(this).data('id');
        let name = $(this).data('name');

        $('#purchase_customer_id').val(customerId);
        $('.customer_name').val(name);
        $('.dropdown-menu').hide();
    });

    // ========================= POOJA SEARCH =========================
    $(document).on('keyup', '.pooja_name', function() {

        let value = $(this).val();
        let row = $(this).closest('.sub_pooja');

        $.ajax({
            url: search_on_pooja,
            data: { search_value: value },
            type: 'GET',
            success: function(response) {

                let dropdown = row.find('.dropdown-menu-pooja');
                dropdown.empty();

                response.forEach(function(res) {
                    dropdown.append(`
                        <a class="dropdown-item pooja-dropdown"
                           href="#"
                           data-id="${res.id}"
                           data-name="${res.pooja_name}"
                           data-code="${res.code}"
                           data-amount="${res.amount}">
                           ${res.pooja_name}
                        </a>
                    `);
                });

                dropdown.show();
            }
        });
    });

    // Select pooja
    $(document).on('click', '.pooja-dropdown', function(e) {

        e.preventDefault();

        let row = $(this).closest('.row');

        row.find('.pooja_name').val($(this).data('name'));
        row.find('.code').val($(this).data('code'));
        row.find('.qty').val(1).prop('readonly', false);
        row.find('.price').val($(this).data('amount')).prop('readonly', false);
        row.find('.total').val($(this).data('amount'));
        row.find('.pooja_id').val($(this).data('id'));

        $('.dropdown-menu-pooja').hide();
    });

    // ========================= SEARCH BY CODE =========================
    $(document).on('keyup', '.code', function() {

        let value = $(this).val();
        let row = $(this).closest('.sub_pooja');

        if (value) {
            $.ajax({
                url: search_on_code,
                data: { search_value: value },
                type: 'GET',
                success: function(response) {

                    if (response.data.length > 0) {

                        let data = response.data[0];

                        row.find('.pooja_name').val(data.pooja_name);
                        row.find('.qty').val(1).prop('readonly', false);
                        row.find('.price').val(data.amount).prop('readonly', false);
                        row.find('.total').val(data.amount);
                        row.find('.pooja_id').val(data.id);

                    } else {
                        row.find('input').val('');
                    }
                }
            });
        }
    });

    // ========================= ADD ROW (FIXED) =========================
    $(document).on('click', '.duplicate-row', function() {

        let firstRow = $('#rowContainer .sub_pooja:first');
        let newRow = firstRow.clone();

        // Clear values
        newRow.find('input').val('');

        // Remove ADD button from new row
        newRow.find('.duplicate-row').remove();

        // Add REMOVE button
        let removeBtn = `
            <button type="button" class="btn btn-danger remove-row">
                Remove
            </button>
        `;

        newRow.find('.col-sm-1:last').html(removeBtn);

        $('#rowContainer').append(newRow);

        newRow.find('.code').focus();
    });

    // ========================= REMOVE ROW =========================
    $(document).on('click', '.remove-row', function() {
        $(this).closest('.sub_pooja').remove();
    });

    // ========================= CALCULATION =========================
    $(document).on('keyup', '.qty, .price', function() {

        let row = $(this).closest('.sub_pooja');
        let qty = parseFloat(row.find('.qty').val()) || 0;
        let price = parseFloat(row.find('.price').val()) || 0;

        row.find('.total').val(qty * price);
    });

    // ========================= UPDATE SUBMIT =========================
    $('.submit_pooja_form').click(function() {

        let btn = $(this);
        btn.prop('disabled', true).text('Updating...');

        let receipt_id = $('#receipt_id').val();
        let get_current_date = $('.current_date').val();
        let get_current_time = $('.current_time').val();
        let payment_method = $('.payment_type').val();
        let bill_desc = $('.bill_desc').val();

        if (!customerId) {
            alert("Please select customer");
            btn.prop('disabled', false).text('Update');
            return;
        }

        let poojaDetails = [];
        let over_all_total = 0;

        $('.sub_pooja').each(function() {

            let row = $(this);

            let qty = row.find('.qty').val();
            if (!qty || qty == 0) return;

            let total = parseFloat(row.find('.total').val()) || 0;

            poojaDetails.push({
                code: row.find('.code').val(),
                pooja_name: row.find('.pooja_name').val(),
                qty: qty,
                price: row.find('.price').val(),
                total: total,
                pooja_id: row.find('.pooja_id').val()
            });

            over_all_total += total;
        });

        if (poojaDetails.length === 0) {
            alert("No pooja selected");
            btn.prop('disabled', false).text('Update');
            return;
        }

        $.ajax({
            url: update_pooja_values,
            type: 'POST',
            data: {
                receipt_id: receipt_id,
                pooja_details: poojaDetails,
                user_id: customerId,
                current_date: get_current_date,
                current_time: get_current_time,
                over_all_total: over_all_total,
                payment_method: payment_method,
                bill_desc: bill_desc
            },
            success: function(response) {

                btn.prop('disabled', false).text('Update');

                if (response.code == 200) {

                    alert("Updated Successfully");
                    window.location.href = '/sevapooja/seva_pooja_report';
                } else {
                    alert("Update failed");
                }
            },
            error: function() {
                btn.prop('disabled', false).text('Update');
                alert("Something went wrong");
            }
        });

    });

});